import { expect, test } from '@playwright/test';
import { TESTIDS } from '../../../e2e/helpers/contract.js';

/**
 * Offline-friendly library cache — failing-first acceptance spec for
 * [TOG-25326](/TOG/issues/TOG-25326) (slice S8: stale list fallback).
 *
 * Builder: build on THIS branch and do NOT edit this file. The flow below is
 * the contract — seed a fresh list, kill the API, reload, and the last-good
 * snapshot must render with a staleness badge instead of a blank screen.
 *
 * RED before the build (no `/library` route, no snapshot cache, no badge);
 * GREEN after. Each test re-seeds inside its own isolated context, so there
 * is no cross-test storage dependency. Reloads (not in-page navigation) are
 * deliberate: the snapshot must survive a real reload via client-side
 * persistence (localStorage / IndexedDB), not in-memory state.
 *
 * Contract hooks: `TESTIDS.libraryItem` (exists in e2e/helpers/contract.ts
 * today) pins each row. `libraryList` / `libraryStaleBadge` are the two new
 * keys the build slice adds to TESTIDS — this spec reads them from the
 * contract when present and falls back to the literal values below until
 * then, so the builder wires the exact strings named here.
 */

const LIBRARY_LIST =
	(TESTIDS as unknown as Record<string, string | undefined>)['libraryList'] ?? 'library-list';
const LIBRARY_STALE_BADGE =
	(TESTIDS as unknown as Record<string, string | undefined>)['libraryStaleBadge'] ??
	'library-stale-badge';
// Existing contract key — the app renders one per track.
const LIBRARY_ITEM = TESTIDS.libraryItem;

interface SeedTrack {
	id: string;
	title: string;
	artist: string;
}

const SEED_TRACKS: SeedTrack[] = [
	{ id: 'seed-track-1', title: 'Seed Track One', artist: 'Seed Artist A' },
	{ id: 'seed-track-2', title: 'Seed Track Two', artist: 'Seed Artist B' }
];

const FRESH_TRACKS: SeedTrack[] = [
	{ id: 'fresh-track-1', title: 'Fresh Track One', artist: 'Fresh Artist C' }
];

/** Fulfill every library-list API read with `tracks` (fresh snapshot seed). */
async function fulfillLibrary(page: import('@playwright/test').Page, tracks: SeedTrack[]) {
	await page.route('**/api/library*', async (route) => {
		await route.fulfill({
			status: 200,
			contentType: 'application/json',
			body: JSON.stringify(tracks)
		});
	});
}

/** Simulate the tunnel/Access/airplane outage: every library API read fails. */
async function blockLibraryApi(page: import('@playwright/test').Page) {
	await page.route('**/api/library*', async (route) => {
		await route.abort('failed');
	});
}

test.describe('library cache with stale list fallback', () => {
	test('fresh load renders the list with no stale badge', async ({ page }) => {
		await fulfillLibrary(page, SEED_TRACKS);
		await page.goto('/library');

		const list = page.getByTestId(LIBRARY_LIST);
		await expect(list, 'library list missing on fresh load').toBeVisible({ timeout: 15_000 });
		await expect(
			page.getByTestId(LIBRARY_ITEM),
			'seeded tracks missing from fresh library list'
		).toHaveCount(SEED_TRACKS.length);
		for (const track of SEED_TRACKS) {
			await expect(list, `fresh list omits seeded track "${track.title}"`).toContainText(
				track.title
			);
		}
		await expect(
			page.getByTestId(LIBRARY_STALE_BADGE),
			'stale badge must not show on a fresh successful load'
		).toBeHidden();
	});

	test('blocked API renders the seeded snapshot with a stale badge', async ({ page }) => {
		// Seed: fresh success persists the last-good snapshot client-side.
		await fulfillLibrary(page, SEED_TRACKS);
		await page.goto('/library');
		await expect(
			page.getByTestId(LIBRARY_ITEM),
			'seed step did not render the fresh list'
		).toHaveCount(SEED_TRACKS.length);

		// Outage: the API is unreachable; reload must NOT blank the screen.
		await page.unroute('**/api/library*');
		await blockLibraryApi(page);
		await page.reload();

		const list = page.getByTestId(LIBRARY_LIST);
		await expect(list, 'library list went blank while offline').toBeVisible({ timeout: 15_000 });
		await expect(
			page.getByTestId(LIBRARY_ITEM),
			'offline list lost the seeded snapshot tracks'
		).toHaveCount(SEED_TRACKS.length);
		for (const track of SEED_TRACKS) {
			await expect(list, `offline snapshot omits seeded track "${track.title}"`).toContainText(
				track.title
			);
		}

		const badge = page.getByTestId(LIBRARY_STALE_BADGE);
		await expect(badge, 'no staleness badge while showing a stale snapshot').toBeVisible({
			timeout: 15_000
		});
		await expect(badge, 'stale badge does not say it is stale').toContainText(/stale/i);
		await expect(badge, 'stale badge names no snapshot time').toContainText(/updated/i);
	});

	test('fresh success after an outage replaces the snapshot and clears the badge', async ({
		page
	}) => {
		// Seed then outage, so a stale snapshot + badge exist.
		await fulfillLibrary(page, SEED_TRACKS);
		await page.goto('/library');
		await expect(page.getByTestId(LIBRARY_ITEM)).toHaveCount(SEED_TRACKS.length);
		await page.unroute('**/api/library*');
		await blockLibraryApi(page);
		await page.reload();
		await expect(page.getByTestId(LIBRARY_STALE_BADGE)).toBeVisible({ timeout: 15_000 });

		// Recovery: a fresh success replaces the snapshot (no stale merge).
		await page.unroute('**/api/library*');
		await fulfillLibrary(page, FRESH_TRACKS);
		await page.reload();

		await expect(page.getByTestId(LIBRARY_ITEM)).toHaveCount(FRESH_TRACKS.length);
		await expect(
			page.getByTestId(LIBRARY_LIST),
			'recovered list still shows the stale snapshot titles'
		).toContainText(FRESH_TRACKS[0]!.title);
		await expect(
			page.getByTestId(LIBRARY_LIST),
			'recovered list merged the stale snapshot instead of replacing it'
		).not.toContainText(SEED_TRACKS[0]!.title);
		await expect(
			page.getByTestId(LIBRARY_STALE_BADGE),
			'stale badge lingered after a fresh successful load'
		).toBeHidden();
	});
});
